session_start();require_once('check-login.php');require_once('smartmark-utils.php');smartmark_ensure_tables($con);$e=mysqli_real_escape_string($con,(string)$_SESSION['USERID']);$id=(int)($_GET['assessment']??0);$r=@mysqli_query($con,"SELECT * FROM tblsmartmarkassessment WHERE assessmentid=$id AND teacherid='$e' LIMIT 1");$a=$r?mysqli_fetch_array($r,MYSQLI_ASSOC):null;if(!$a){exit('Assessment not found.');}$opts=smartmark_options($a['optioncount']);?><!doctype html><html><head><title>Answer sheet</title><style>body{font-family:Arial;margin:25px}.head{border:3px solid #087d70;padding:18px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;margin-top:20px}.q{padding:7px;border-bottom:1px dotted #999}.b{display:inline-grid;place-items:center;border:1px solid;border-radius:50%;width:24px;height:24px;margin-left:8px;font-size:11px}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print</button><div class="head"><h1>SMARTMARK</h1><b><?php echo htmlspecialchars($a['title']);?></b><p>Name: ______________________________ Student ID: ______________</p><p>Shade one circle per question.</p></div><div class="grid"><?php for($n=1;$n<=(int)$a['questioncount'];$n++){?><div class="q"><b><?php echo $n;?>.</b><?php foreach($opts as $o){?><span class="b"><?php echo $o;?></span><?php }?></div><?php }?></div></body></html>
